export function Sidebar({
  title = "{{title}}",
  side = "{{side}}",
  width = {{width}},
  collapsed = {{collapsed}},
  accent = "{{accent}}",
}) {
  const w = collapsed ? 48 : width;
  return (
    <div style={{ display: "flex", flexDirection: side === "right" ? "row-reverse" : "row", height: 150, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430", border: "1px solid #24143022" }}>
      <aside className="sidebar-aside" style={{ flex: "none", boxSizing: "border-box", width: w, background: "#241430", color: "#FAF7F2", padding: "12px 10px", overflow: "hidden" }}>
        <div style={{ fontWeight: 700, marginBottom: 10, paddingBottom: 8, borderBottom: `2px solid ${accent}`, whiteSpace: "nowrap" }}>{!collapsed && title}</div>
        <div style={{ height: 8, borderRadius: 4, background: accent, marginBottom: 8 }} />
        <div style={{ height: 8, borderRadius: 4, background: "#FAF7F233", marginBottom: 8 }} />
        <div style={{ height: 8, borderRadius: 4, background: "#FAF7F233", marginBottom: 8 }} />
      </aside>
      <main style={{ flex: 1, background: "#FAF7F2", display: "flex", alignItems: "center", justifyContent: "center", color: "#24143066" }}>Main content</main>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .sidebar-aside { transition: width .15s; }
        }
      `}</style>
    </div>
  );
}
